private void Backtrack(int[] nums, bool[] visited, List<Integer> comb, List<List<Integer>> result)
{
    if (comb.Count == nums.Length)
    {
        result.Add(new List<Integer>(comb));
        return;
    }
    for (int i = 0; i < nums.Length; i++)
    {
        if (!visited[i])
        {
            comb.Add(nums[i]);
            visited[i] = true;
            Backtrack(nums, visited, comb, result);
            visited[i] = false;
            comb.RemoveAt(comb.Count - 1);
        }
    }
}

