private static void findLargestSubstring(List<String> strings) {
    // Sort the list of strings in descending order of length
    Collections.sort(strings, (s1, s2) -> Integer.compare(s2.length(), s1.length()));

    // Initialize maxLength to the length of the first string in the list
    int maxLength = strings.get(0).length();

    // Iterate over the list of strings
    for (int i = 1; i < strings.size(); i++) {
        String currentString = strings.get(i);

        // Check if the current string is a prefix of any of the other strings
        for (int j = i + 1; j < strings.size(); j++) {
            if (currentString.startsWith(strings.get(j))) {
                // If we find a match, update maxLength to the length of the current string
                maxLength = Math.max(maxLength, currentString.length());
                break;
            }
        }

        // Reverse the current string and check if it is a suffix of any of the other strings
        String reversedCurrentString = new StringBuilder(currentString).reverse().toString();
        for (int j = i + 1; j < strings.size(); j++) {
            if (reversedCurrentString.startsWith(strings.get(j))) {
                // If we find a match, update maxLength to the length of the current string
                maxLength = Math.max(maxLength, currentString.length());
                break;
            }
        }
    }

    System.out.println(maxLength);
}

