    Set<String> uniqueDeposits = new HashSet<>();
    // Iterate over the grid
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            // If the current cell has oil, add it to the set
            if (grid[i][j] == '@') {
                uniqueDeposits.add(i + " " + j);
