public static int countOilDeposits(char[][] grid) {
    int count = 0;
    int row = grid.length;
    int column = grid[0].length;
    for (int i = 0; i < row; i++) {
        for (int j = 0; j < column; j++) {
            if (grid[i][j] == '@') {
                count++;
                grid[i][j] = '#';
                dfs(grid, i, j);
            }
        }
    }
    return count;
}

private static void dfs(char[][] grid, int i, int j) {
    int row = grid.length;
    int column = grid[0].length;
    if (i - 1 >= 0 && i + 1 < row && j - 1 >= 0 && j + 1 < column) {
        if (grid[i - 1][j] == '@') {
            grid[i - 1][j] = '#';
            dfs(grid, i - 1, j);
        }
        if (grid[i + 1][j] == '@') {
            grid[i + 1][j] = '#';
            dfs(grid, i + 1, j);
        }
        if (grid[i][j - 1] == '@') {
            grid[i][j - 1] = '#';
            dfs(grid, i, j - 1);
        }
        if (grid[i][j + 1] == '@') {
            grid[i][j + 1] = '#';
            dfs(grid, i, j + 1);
        }
    }
}

class Graph:
    def __init__(self, grid):
        self.grid = grid
        self.n_rows = len(grid)
        self.n_cols = len(grid[0])
        self.adj_list = {}
        for row in range(self.n_rows):
            for col in range(self.n_cols):
                node = (row, col)
                self.adj_list[node] = []
                for neighbor in self.neighbors(node):
                    self.adj_list[node].append(neighbor)

    def count_clusters(self):
        clusters = 0
        while self.adj_list:
            node = list(self.adj_list.keys())[0]
            self.visit(node)
            clusters += 1
        return clusters

    def visit(self, node):
        self.adj_list[node].remove(node)
        for neighbor in self.neighbors(node):
            if neighbor in self.adj_list:
                self.visit(neighbor)

    def neighbors(self, node):
        row, col = node
        return [(row-1, col), (row+1, col), (row, col-1), (row, col+1)]

