    int numDeposits = 0;

    // Loop through each row of the grid
    for (int row = 0; row < grid.length; row++) {
        // Loop through each column of the grid
        for (int col = 0; col < grid[row].length; col++) {
            // If the current cell contains an oil deposit
            if (grid[row][col] == '@') {
                // Check the neighboring cells
                boolean found = false;
                for (int i = -1; i <= 1; i++) {
                    for (int j = -1; j <= 1; j++) {
                        // If the neighboring cell contains an oil deposit
                        if (grid[row + i][col + j] == '@') {
                            found = true;
                            break;
                        }
                    }
                }

                // If no matching oil deposits were found, increment the number of distinct oil deposits
                if (!found) {
                    numDeposits++;
                }
            }
        }
    }

    return numDeposits;
}

