public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a 2D array to represent the n-teresting space
    boolean[][] maze = new boolean[n][n];

    // Set the starting and ending n-tersections to true
    maze[start[0]][start[1]] = true;
    maze[end[0]][end[1]] = true;

    // Loop through each path and set the adjacent n-tersections to true
    for (int[] path : paths) {
        maze[path[0]][path[1]] = true;
        maze[path[2]][path[3]] = true;
    }

    // Perform breadth-first search from the starting n-tersection
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int i = current[0];
        int j = current[1];

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (maze[i][j]) {
            return "cannot be travelled";
        }

        // If the current n-tersection is not the ending n-tersection, mark its neighbors as visited
        for (int[] neighbor : getNeighbors(maze, i, j)) {
            if (!maze[neighbor[0]][neighbor[1]]) {
                queue.add(neighbor);
                maze[neighbor[0]][neighbor[1]] = true;
            }
        }
    }

    // If the ending n-tersection is not visited, return "cannot be travelled"
    if (!maze[end[0]][end[1]]) {
        return "cannot be travelled";
    }

    // Return "can be travelled" if the ending n-tersection is visited
    return "can be travelled";
}

public static List<int[]> getNeighbors(boolean[][] maze, int x, int y) {
    List<int[]> neighbors = new ArrayList<>();
    if (x > 0) {
        neighbors.add(new int[] {x - 1, y});
    }
    if (x < maze.length - 1) {
        neighbors.add(new int[] {x + 1, y});
    }
    if (y > 0) {
        neighbors.add(new int[] {x, y - 1});
    }
    if (y < maze[0].length - 1) {
        neighbors.add(new int[] {x, y + 1});
    }
    return neighbors;
}

