    // Initialize a set to keep track of the n-tersections that have been visited
    Set<int[]> visited = new HashSet<>();

    // While the stack is not empty, pop the top n-tersection from the stack
    while (!stack.isEmpty()) {
        int[] current = stack.pop();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // If the current n-tersection has not been visited before, mark it as visited
        if (!visited.contains(current)) {
            visited.add(current);

            // Get the list of adjacent n-tersections for the current n-tersection
            List<int[]> adjacents = getAdjacent(current, paths);

            // For each adjacent n-tersection, push it to the stack
            for (int[] adjacent : adjacents) {
                stack.push(adjacent);
            }
        }
    }

    // If the ending n-tersection was not found in the traversal, return "cannot be travelled"
    return "cannot be travelled";
}

private static List<int[]> getAdjacent(int[] n, int[][] paths) {
    List<int[]> adjacents = new ArrayList<>();

    // Iterate over all paths in the n-teresting space
    for (int[][] path : paths) {
        int[] pathStart = path[0];
        int[] pathEnd = path[1];

        // If the current n-tersection is the start of the path, add the end of the path to the list of adjacents
        if (Arrays.equals(n, pathStart)) {
            adjacents.add(pathEnd);
        }
    }

    return adjacents;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of n-tersections that have been visited
    boolean[][] visited = new boolean[n][n];
    int[][] directions = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    visited[start[0]][start[1]] = true;
    while (!queue.isEmpty()) {
        int[] current = queue.remove();
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        for (int[] direction : directions) {
            int[] next = new int[]{current[0] + direction[0], current[1] + direction[1]};
            if (next[0] >= 0 && next[0] < n && next[1] >= 0 && next[1] < n
                    && !visited[next[0]][next[1]]
                    && paths[current[0]][current[1]][next[0]][next[1]] != 0) {
                visited[next[0]][next[1]] = true;
                queue.add(next);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
