    Set<String> visited = new HashSet<>();

    // Create a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Check all adjacent n-tersections
        for (int[] path : paths) {
            // Calculate the new n-tersection coordinates
            int newX = current[0] + path[0];
            int newY = current[1] + path[1];

            // Check if the new n-tersection is within the n-teresting space
            if (newX >= 0 && newX < n && newY >= 0 && newY < n) {
                // Check if the new n-tersection has already been visited
                String newKey = newX + "," + newY;
                if (!visited.contains(newKey)) {
                    // Mark the new n-tersection as visited
                    visited.add(newKey);

                    // Add the new n-tersection to the queue
                    queue.add(new int[]{newX, newY});
                }
            }
        }
    }

    // If the ending n-tersection was not found, return "cannot be travelled"
    return "cannot be travelled";
}

