public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with the given nodes and edges
    Graph graph = new Graph(n);
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }

    // Initialize a priority queue to store the nodes to visit
    Queue<Integer> queue = new PriorityQueue<>(n);
    queue.add(0);

    // Initialize a boolean array to mark the nodes that have been visited
    boolean[] visited = new boolean[n];
    visited[0] = true;

    // Initialize a variable to store the minimum time required to collect all the apples and return to node 0
    int minTime = 0;

    // Loop until the priority queue is empty
    while (!queue.isEmpty()) {
        // Get the node with the minimum time value
        int currentNode = queue.poll();
        int currentTime = graph.getNode(currentNode).getTime();

        // If the current node has an apple, increase the minimum time
        if (hasApple[currentNode]) {
            minTime += currentTime;
        }

        // Loop through the children of the current node
        for (int child : graph.getChildren(currentNode)) {
            // If the child has been visited, skip it
            if (visited[child]) {
                continue;
            }

            // Update the minimum time and mark the child as visited
            minTime = Math.min(minTime, currentTime + graph.getEdge(currentNode, child).getTime());
            visited[child] = true;

            // Add the child to the priority queue
            queue.add(child);
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minTime;
}

