public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int target = sum * 2;
    int n = nums.length;
    for (int i = 1; i < n; i++) {
        if (target % i == 0 && canSplit(nums, i, target / i)) {
            return true;
        }
    }
    return false;
}

private boolean canSplit(int[] nums, int m, int average) {
    int sum = 0;
    for (int i = 0; i < m; i++) {
        sum += nums[i];
    }
    if (sum > average) {
        return false;
    }
    return canSplit(nums, m + 1, average - sum);
}

