        } else {
            splitArrays[1][rightIndex++] = nums[i];
        }
    }
    return splitArrays;
}

private boolean isValidSplit(int[][] splitArrays) {
    double leftAverage = getAverage(splitArrays[0]);
    double rightAverage = getAverage(splitArrays[1]);
    return Math.abs(leftAverage - rightAverage) < 1e-6;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    for (int i = 0; i < cost.length; i++) {
        int currentCost = cost[i];
        if (i == 0) {
            minCost = currentCost;
        } else if (i == 1) {
            minCost = Math.min(minCost, currentCost + cost[i - 1]);
        } else {
            minCost = Math.min(minCost, currentCost + Math.min(cost[i - 1], cost[i - 2]));
        }
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return dp[n];
}

