public int minCostClimbingStairs(int[] cost) {
    int costFromStart = 0, costFromEnd = 0;
    for (int i = 0; i < cost.length; i += 2) {
        costFromStart += cost[i];
    }
    for (int i = cost.length - 1; i >= 0; i -= 2) {
        costFromEnd += cost[i];
    }
    return Math.min(costFromStart, costFromEnd);
}

public int minCostClimbingStairs(int[] cost) {
    int[] memo = new int[cost.length];
    return Math.min(minCostClimbingStairs(cost, 0, memo), minCostClimbingStairs(cost, 1, memo));
}

private int minCostClimbingStairs(int[] cost, int index, int[] memo) {
    if (index >= cost.length) {
        return 0;
    }
    if (memo[index] != 0) {
        return memo[index];
    }
    int cost1 = cost[index] + minCostClimbingStairs(cost, index + 1, memo);
    int cost2 = cost[index] + minCostClimbingStairs(cost, index + 2, memo);
    memo[index] = Math.min(cost1, cost2);
    return memo[index];
}

