    int n = s.length();
    for (int i = 0; i <= n - k; i++) {
        String substr = s.substring(i, i + k);
        int num = Integer.parseInt(substr, 2);
        for (int j = 0; j < (1 << k); j++) {
            String bin = Integer.toBinaryString(j);
            if (bin.length() < k) {
                bin = "0" + bin;
            }
            if (!s.contains(bin)) {
