    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int min = Integer.MAX_VALUE;
    int max = Integer.MIN_VALUE;

    for (int i = 0; i < n; i++) {
        min = Math.min(min, arr[i]);
    }

    for (int i = 0; i < n; i++) {
        max = Math.max(max, arr[i]);
    }

    if (min == max) {
        return 0;
    }

    int target = (min + max) / 2;
    int count = 0;

    for (int i = 0; i < n; i++) {
        if (arr[i] < target) {
            count += target - arr[i];
        } else if (arr[i] > target) {
            count += arr[i] - target;
        }
    }

    return count;
}

