        int fib2 = 1;
        int fibN = 0;

        while (fibN < k) {
            fibN = fib1 + fib2;
            fib1 = fib2;
            fib2 = fibN;
            fibList.add(fibN);
        }

        int minNumFib = 0;
        for (int i = fibList.size() - 1; i >= 0; i--) {
            int currFib = fibList.get(i);
            if (currFib <= k) {
                minNumFib++;
                k -= currFib;
            }
        }

        return minNumFib;
    }

