public static boolean hasUniqueDigits(int num) {
    if (num == 0) {
        return true;
    }
    int seenDigits = 0;
    while (num > 0) {
        int digit = num % 10;
        if ((seenDigits & (1 << digit)) > 0) {
            return false;
        }
        seenDigits |= (1 << digit);
        num /= 10;
    }
    return true;
}

