public String makeGood(String s) {
  StringBuilder sb = new StringBuilder(s);
  for (int i = 1; i < sb.length(); i++) {
    char c1 = sb.charAt(i - 1);
    char c2 = sb.charAt(i);
    if (Character.isLowerCase(c1) && Character.isUpperCase(c2) && c1 == (c2 - 32)) {
      sb.deleteCharAt(i - 1);
      sb.deleteCharAt(i - 1);
      i = 0;
    }
  }
  return sb.toString();
}

public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (i == 0) {
            sb.append(c);
        } else {
            char lastChar = sb.charAt(sb.length() - 1);
            int diff = Math.abs(c - lastChar);
            if (diff == 32 || diff == -32) {
                sb.deleteCharAt(sb.length() - 1);
            } else {
                sb.append(c);
            }
        }
    }
    return sb.toString();
}

public String makeGood(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (stack.isEmpty()) {
            stack.push(c);
        } else {
            char top = stack.peek();
            if (Math.abs(top - c) == 32) {
                stack.pop();
            } else {
                stack.push(c);
            }
        }
    }
    StringBuilder sb = new StringBuilder();
    while (!stack.isEmpty()) {
        sb.append(stack.pop());
    }
    return sb.toString();
}

