public int maxUniqueSplit(String s) {
    // Initialize a set to store the unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();

    // Initialize the maximum number of unique substrings
    int maxUniqueSubstrings = 0;

    // Loop through each character in the string
    for (int i = 0; i < s.length(); i++) {
        // Create a substring starting from the current character
        String substring = s.substring(i);

        // Check if the substring is unique
        if (!uniqueSubstrings.contains(substring)) {
            // If the substring is unique, add it to the set and increment the maximum number of unique substrings
            uniqueSubstrings.add(substring);
            maxUniqueSubstrings++;
        }
    }

    return maxUniqueSubstrings;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 0;
    for (int i = 1; i <= s.length(); i++) {
        String[] subs = getAllSubstrings(s, i);
        if (isUnique(subs) && subs.length > max) {
            max = subs.length;
        }
    }
    return max;
}

private String[] getAllSubstrings(String s, int size) {
    int len = s.length();
    String[] subs = new String[len - size + 1];
    for (int i = 0; i < len - size + 1; i++) {
        subs[i] = s.substring(i, i + size);
    }
    return subs;
}

private boolean isUnique(String[] subs) {
    Set<String> set = new HashSet<>();
    for (String sub : subs) {
        if (set.contains(sub)) {
            return false;
        }
        set.add(sub);
    }
    return true;
}

