    // Check if n is less than 1 or not a power of 2
    if (n < 1 || n > 1 && n % 2 != 0) {
        return false;
    }
    // Check if n is a power of 2
    while (n > 1) {
        if (n % 2 != 0) {
            return false;
        }
        n /= 2;
    }
    return true;
}

