                horizontal[i][j]++;
                vertical[i][j]++;
                diagonal[i][j]++;
                antiDiagonal[i][j]++;
                if (i > 0) {
                    horizontal[i][j] += horizontal[i - 1][j];
                    vertical[i][j] += vertical[i - 1][j];
                    diagonal[i][j] += diagonal[i - 1][j];
                    antiDiagonal[i][j] += antiDiagonal[i - 1][j];
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j] = 0;
                diagonal[i][j] = 0;
                antiDiagonal[i][j] = 0;
