def squarePermutations(A):
    n = len(A)
    if n == 1:
        return 1
    if n == 2:
        return 2 if A[0] + A[1] in {1, 2, 4, 16} else 0
    if n == 3:
        return 6 if A[0] + A[1] in {1, 2, 4, 16} and A[1] + A[2] in {1, 2, 4, 16} else 0

    def is_square(x):
        return int(round(x ** 0.5)) ** 2 == x

    def count_permutations(i):
        if i == n - 1:
            return 1 if is_square(A[i - 1] + A[i]) else 0
        else:
            count = 0
            for j in range(i, n):
                if is_square(A[i - 1] + A[j]):
                    count += count_permutations(j + 1)
            return count

    return count_permutations(1)

public static int squarePermutations(int[] A) {
    // Initialize a set to store the unique permutations
    Set<String> permutations = new HashSet<>();

    // Get the sum of each pair of adjacent elements
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];

        // Check if the sum is a perfect square
        if (isPerfectSquare(sum)) {
            // If it is, add the permutation to the set
            permutations.add(A[i] + " " + A[i + 1]);
        }
    }

    // Return the size of the set
    return permutations.size();
}

public static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int squarePermutations(int[] A) {
    // Initialize the number of square permutations to 0
    int count = 0;

    // Iterate over all permutations of the input array
    for (int i = 0; i < Math.pow(2, A.length); i++) {
        // Convert the binary representation of i to binary
        int[] permutation = new int[A.length];
        for (int j = 0; j < A.length; j++) {
            permutation[j] = (i >> j) & 1;
        }

        // Check if the sum of each pair of adjacent elements in the permutation is a perfect square
        boolean isSquare = true;
        for (int j = 0; j < A.length - 1; j++) {
            if ((permutation[j] + permutation[j + 1]) % 4 != 0) {
                isSquare = false;
                break;
            }
        }

        // If the permutation is a square, increment the count
        if (isSquare) {
            count++;
        }
    }

    return count;
}

