public static int largestRectangleArea(int[] heights) {
    // Sort the heights array in ascending order
    Arrays.sort(heights);

    int maxArea = 0;
    int previousHeight = 0;

    // Iterate through the heights array and calculate the area of each rectangle
    for (int i = 0; i < heights.length; i++) {
        int currentHeight = heights[i];
        int width = i - previousHeight;
        int area = width * currentHeight;
        maxArea = Math.max(maxArea, area);
        previousHeight = currentHeight;
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int n = heights.length;
    int left[] = new int[n];
    int right[] = new int[n];

    // Initialize the left and right arrays
    left[0] = -1;
    right[n - 1] = n;

    // Compute the left and right arrays
    for (int i = 1; i < n; i++) {
        int p = i - 1;
        while (p >= 0 && heights[i] <= heights[p]) {
            p = left[p];
        }
        left[i] = p;
    }

    for (int i = n - 2; i >= 0; i--) {
        int p = i + 1;
        while (p < n && heights[i] <= heights[p]) {
            p = right[p];
        }
        right[i] = p;
    }

    // Compute the maximum area
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, (right[i] - left[i] - 1) * heights[i]);
    }

    return maxArea;
}

